<script>
export default {
  name: 'UserProfile',
  data() {
    return {
      roles: ['Aspiring Fullstack Developer', 'Aspiring DevOps Engineer'],
      typedRole: '',
      roleIndex: 0,
      charIndex: 0,
      isDeleting: false,
      typingTimer: null,
    }
  },
  mounted() {
    this.typeRole()
  },
  beforeUnmount() {
    clearTimeout(this.typingTimer)
  },
  methods: {
    typeRole() {
      const current = this.roles[this.roleIndex]
      if (this.isDeleting) {
        this.typedRole = current.substring(0, this.charIndex - 1)
        this.charIndex--
      } else {
        this.typedRole = current.substring(0, this.charIndex + 1)
        this.charIndex++
      }

      let delay = this.isDeleting ? 60 : 100

      if (!this.isDeleting && this.charIndex === current.length) {
        delay = 1800
        this.isDeleting = true
      } else if (this.isDeleting && this.charIndex === 0) {
        this.isDeleting = false
        this.roleIndex = (this.roleIndex + 1) % this.roles.length
        delay = 400
      }

      this.typingTimer = setTimeout(this.typeRole, delay)
    },
  },
}
</script>

